import sys
sys.setrecursionlimit(100000)

def calc(expr: str) -> int | str:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        elif c in '+-*/%^()':
            tokens.append(c)
            i += 1
        else:
            i += 1  # not expected; input is valid
    pos = 0
    try:
        def parse_add():
            nonlocal pos
            v = parse_mul()
            while pos < len(tokens) and tokens[pos] in ('+', '-'):
                op = tokens[pos]; pos += 1
                r = parse_mul()
                v = v + r if op == '+' else v - r
            return v
        def parse_mul():
            nonlocal pos
            v = parse_unary()
            while pos < len(tokens) and tokens[pos] in ('*', '/', '%'):
                op = tokens[pos]; pos += 1
                r = parse_unary()
                if op == '*':
                    v = v * r
                elif op == '/':
                    if r == 0: raise ZeroDivisionError
                    q = abs(v) // abs(r)
                    if (v < 0) != (r < 0): q = -q
                    v = q
                else:
                    if r == 0: raise ZeroDivisionError
                    q = abs(v) // abs(r)
                    if (v < 0) != (r < 0): q = -q
                    v = v - r * q
            return v
        def parse_unary():
            nonlocal pos
            if pos < len(tokens) and tokens[pos] == '-':
                pos += 1
                return -parse_unary()
            return parse_power()
        def parse_power():
            nonlocal pos
            base = parse_atom()
            if pos < len(tokens) and tokens[pos] == '^':
                pos += 1
                exp = parse_unary()
                if exp < 0: raise ZeroDivisionError
                return base ** exp
            return base
        def parse_atom():
            nonlocal pos
            t = tokens[pos]
            if t == '(':
                pos += 1
                v = parse_add()
                pos += 1  # ')'
                return v
            pos += 1
            return t
        return parse_add()
    except (ZeroDivisionError, IndexError):
        return "error"
